package main

import (
	"context"
	"log/slog"
	"sync"
	"time"
)

// janitorTask is one named registry task: its tick interval and the work it
// runs each tick. interval 0 (or negative) DISABLES the task — the env knob's
// off position: the task neither boot-runs nor ticks while every other task
// is untouched (artwork: only the art task is knob-gated).
type janitorTask struct {
	name     string
	interval time.Duration
	fn       func(context.Context)
}

// janitor is the named multi-task sweep registry (artwork D8), the
// generalization of the single-ticker sweep loop. Each enabled task
// keeps its own ticker goroutine, so one slow pass never delays another
// task's cadence; every task yields to the process context. Day-one tasks:
// streams (the packaged-playback sweep folded in unchanged) and art (the
// internal/art settle+GC walk, its interval the knob-gated one).
type janitor struct {
	tasks []janitorTask
}

// newJanitor registers tasks in call order.
func newJanitor(tasks ...janitorTask) *janitor { return &janitor{tasks: tasks} }

// runBoot executes every enabled task ONCE, in registration order — the
// boot-run is the same per-task pass a tick runs, not a bulk path (artwork:
// a restarted server resumes its settle before serving).
func (j *janitor) runBoot(ctx context.Context) {
	for _, t := range j.tasks {
		if t.interval <= 0 {
			continue
		}
		t.fn(ctx)
	}
}

// run ticks every enabled task at its own interval until the process context
// is cancelled. Blocks until all task loops have returned.
func (j *janitor) run(ctx context.Context) {
	var wg sync.WaitGroup
	for _, t := range j.tasks {
		if t.interval <= 0 {
			slog.Info("janitor: task disabled", "task", t.name)
			continue
		}
		wg.Add(1)
		go func(task janitorTask) {
			defer wg.Done()
			ticker := time.NewTicker(task.interval)
			defer ticker.Stop()
			for {
				select {
				case <-ctx.Done():
					return
				case <-ticker.C:
					task.fn(ctx)
				}
			}
		}(t)
	}
	wg.Wait()
}
